import { attachSaveStatus } from "./save-status.js";
import { createTrailingTask } from "./trailing-task.js";

export function createDraftEditor({ store, timers, renderDocument, renderStatus }) {
  let current = null;
  let navigationVersion = 0;
  function retireCurrent() {
    const leaving = current;
    current = null;
    if (leaving) {
      leaving.stop();
      leaving.save.flush();
    }
  }
  function close() {
    const version = ++navigationVersion;
    retireCurrent();
    // Flushing can synchronously navigate through a store subscriber. Do not
    // clear a document installed by that newer request.
    if (navigationVersion === version) renderDocument(null);
    return navigationVersion === version;
  }
  return {
    open(id, visit) {
      const version = ++navigationVersion;
      retireCurrent();
      if (navigationVersion !== version) return false;
      renderDocument(null);
      if (navigationVersion !== version) return false;
      const save = createTrailingTask(text => store.write(id, text), 120, timers);
      current = { id, visit, save, stop: attachSaveStatus(store, id, renderStatus) };
      renderDocument({ id, visit, text: store.read(id) });
      return navigationVersion === version;
    },
    edit(text) {
      if (current) current.save.push(text);
    },
    selection: () => current && { id: current.id, visit: current.visit },
    close,
  };
}

